import{_ as i,o as s,c as a,aO as o}from"./chunks/framework.BFrk9dwu.js";const l="/recipes/tiger-chicken-feet.jpg",e="/recipes/tiger-chicken-feet/top-2.jpg",c="/recipes/tiger-chicken-feet/top-3.jpg",r="/recipes/tiger-chicken-feet/step-1-a.jpg",n="/recipes/tiger-chicken-feet/step-1-b.jpg",g="/recipes/tiger-chicken-feet/step-2-b.jpg",d="/recipes/tiger-chicken-feet/step-2-a.jpg",p="/recipes/tiger-chicken-feet/step-3-a.jpg",h="/recipes/tiger-chicken-feet/step-4-a.jpg",f="/recipes/tiger-chicken-feet/step-4-b.jpg",_="/recipes/tiger-chicken-feet/step-6-a.jpg",m="/recipes/tiger-chicken-feet/step-6-b.jpg",v=JSON.parse('{"title":"虎皮鸡爪","description":"炸出虎皮、泡冷水起皱、卤到软糯的虎皮鸡爪做法，含不起皮、发硬、溅油的排查","frontmatter":{"date":"2026-11-15T16:10:42.000Z","title":"虎皮鸡爪","description":"炸出虎皮、泡冷水起皱、卤到软糯的虎皮鸡爪做法，含不起皮、发硬、溅油的排查","permalink":"/pages/720aa1","categories":["life","recipes"]},"headers":[],"relativePath":"life/recipes/tiger-chicken-feet.md","filePath":"life/recipes/tiger-chicken-feet.md","lastUpdated":1794808782000}'),u={name:"life/recipes/tiger-chicken-feet.md"};function b(k,t,y,j,z,x){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="虎皮鸡爪" tabindex="-1">虎皮鸡爪 <a class="header-anchor" href="#虎皮鸡爪" aria-label="Permalink to &quot;虎皮鸡爪&quot;">​</a></h1><div class="recipe-gallery"><img src="'+l+'" alt="虎皮鸡爪成品：白瓷盘里酱红油亮的鸡爪，撒了白芝麻和葱花"><img src="'+e+'" alt="特写：鸡爪表皮起皱鼓泡的虎皮纹"><img src="'+c+'" alt="筷子夹起一只鸡爪，旁边一碗白米饭"><img loading="lazy" src="'+r+'" alt="白盘里洗净的生鸡爪，旁边一把小剪刀"></div><p>虎皮鸡爪的核心就一句：<strong>炸出泡，再泡回皱</strong>。皮炸到起泡、立刻泡冷水，皱褶才起得来；后面卤多久只决定软糯，决定不了那层虎皮。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>鸡爪</td><td>剪掉爪尖，指甲缝里的黄膜也撕掉</td></tr><tr><td>生姜</td><td>焯水、炒香料</td></tr><tr><td>大蒜</td><td>拍破</td></tr></tbody></table><p><strong>配料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>食用油</td><td>用于炸，炸完滤一下还能炒菜</td></tr><tr><td>冰糖</td><td>给亮度和回口</td></tr><tr><td>生抽</td><td></td></tr><tr><td>老抽</td><td>只调色，多了发黑</td></tr><tr><td>料酒</td><td>用于焯水、炒制</td></tr><tr><td>八角</td><td></td></tr><tr><td>干辣椒</td><td>剪成段</td></tr><tr><td>花椒</td><td></td></tr><tr><td>热水</td><td></td></tr><tr><td>盐</td><td></td></tr><tr><td>葱花</td><td>出锅撒</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>剪爪尖。</strong> 鸡爪剪掉爪尖，指甲缝里的黄膜撕干净，冲洗两遍。不清干净，卤出来有股土腥味。</p><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="剪掉爪尖后的鸡爪，爪尖收在小碟里"><img loading="lazy" src="'+r+'" alt="白盘里洗净的生鸡爪，旁边一把小剪刀"></figure></li><li><p><strong>焯水控干。</strong> 冷水下锅，加姜、料酒，水开后撇净浮沫煮一会捞出。<strong>一定要彻底控干、晾到表面不湿</strong>，带水下油锅会炸得满厨房都是。</p><figure class="recipe-shots"><img loading="lazy" src="'+g+'" alt="焯好的鸡爪控在沥水篮里晾干"><img loading="lazy" src="'+d+'" alt="鸡爪冷水下锅，水面浮起灰白浮沫"></figure></li><li><p><strong>下油锅炸。</strong> 油烧到六成热（筷子插进去周围冒小泡），鸡爪分批下锅，<strong>立刻盖上锅盖</strong>，中火炸，炸到表面金黄、起小泡。炸的时候别翻，等它自己浮起来再动。</p><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="鸡爪在热油里深炸，油面密集起泡"></figure></li><li><p><strong>立刻泡冷水。</strong> 炸好的鸡爪直接丢进冷水盆，泡 30 分钟。这一步是虎皮的关键，<strong>趁热泡</strong>，凉了再泡起不来皱。</p><figure class="recipe-shots"><img loading="lazy" src="'+h+'" alt="炸好的鸡爪泡在冷水盆里"><img loading="lazy" src="'+f+'" alt="泡好后鸡爪表皮鼓起一层层虎皮皱"></figure></li><li><p><strong>炒香料。</strong> 锅留油，下姜片、蒜瓣、八角、干辣椒、花椒小火炒香。</p></li><li><p><strong>鸡爪入锅。</strong> 泡好的鸡爪沥干下锅翻匀，沿锅边淋料酒，加生抽、老抽、冰糖，倒热水没过鸡爪。</p><figure class="recipe-shots"><img loading="lazy" src="'+_+'" alt="鸡爪下锅与香料、红油一起翻拌上色"><img loading="lazy" src="'+m+'" alt="加热水没过鸡爪，盖上盖子小火卤"></figure></li><li><p><strong>小火卤 40 分钟。</strong> 大火烧开转小火，盖盖卤 40 分钟。喜欢更软糯就卤 60 分钟，别超过 90 分钟，皮会烂。</p></li><li><p><strong>收汁出锅。</strong> 转大火收汁 5 分钟，收到酱汁裹住鸡爪、锅底只剩一层浓汁，尝味补盐，撒白芝麻和葱花。</p><figure class="recipe-shots"><img src="'+e+'" alt="特写：鸡爪表皮起皱鼓泡的虎皮纹"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>必须彻底晾干再下油锅</strong>：带水炸会溅油，也炸不出均匀的泡。</li><li><strong>趁热泡冷水</strong>：炸完立刻泡，皱褶才起得来，凉了泡是白炸。</li><li><strong>油温六成、盖锅盖</strong>：低了炸不泡，高了外皮焦里没熟。</li><li><strong>收汁到裹住就停</strong>：鸡爪胶质多，汁收过头会发黏糊嘴。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>不想炸就用空气炸锅：200℃ 烤 20 分钟，中途翻一次面，出来一样起泡，还没有溅油的危险。炸好后同样要泡冷水。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>不起虎皮</strong>：没晾干、油温不够，或者炸完没有立刻泡冷水。</li><li><strong>皮硬嚼不动</strong>：卤的时间不够，40 分钟是底线。</li><li><strong>溅油</strong>：带水下锅，或者一次下太多、油温骤降。</li><li><strong>腥味重</strong>：爪尖没剪、指甲缝没洗净，焯水也没撇浮沫。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',15)])])}const P=i(u,[["render",b]]);export{v as __pageData,P as default};
